internal fun translateSleepLab(language: AppLanguage, source: String): String? {
    val values = sleepLabTexts[source] ?: return null
    return when (language) {
        AppLanguage.CHINESE -> source
        AppLanguage.ENGLISH -> values[0]
        AppLanguage.FRENCH -> values[1]
        AppLanguage.ARABIC -> values[2]
    }
}
